<script setup>
import { displayTimeZone, locale, t } from '../i18n/index.js';
import { onMounted, ref } from 'vue';
import Icon from './Icon.vue';
defineProps({ loading: Boolean, marking: Boolean, unread: Number, error: String, page: {type:Number,default:1}, pageCount: {type:Number,default:1}, notifications: Array });
const emit = defineEmits(['close', 'open', 'page', 'reload', 'read-all']);
const dialog = ref(null);
const labels = { assigned: t('交給你一件紙條'), commented: t('回覆紙條'), forwarded: t('傳遞紙條給你'), edited: t('更新紙條內容'), completed: t('完成你的交辦'), reopened: t('重新開啟紙條'), returned: t('將紙條退回給你'), canceled: t('取消紙條'), converted: t('將紙條轉成正式卡片') };
onMounted(() => dialog.value.showModal());
</script>
<template>
  <dialog ref="dialog" class="todo-notifications" aria-labelledby="todo-notification-heading" @cancel.prevent="emit('close')" @click="event => { if (event.target === dialog) emit('close'); }"><header><h2 id="todo-notification-heading">{{ t('通知') }}</h2><button class="icon-button" :aria-label="t('關閉通知')" @click="emit('close')"><Icon name="close" /></button></header><button class="text-button mark-all-read" :disabled="!unread || marking || loading" @click="emit('read-all')">{{ marking ? t('處理中…') : t('全部標為已讀') }}</button><p v-if="loading" role="status">{{ t('載入通知中…') }}</p><p v-if="error" class="error-box" role="alert">{{ t(error) }}<button class="text-button" @click="emit('reload')">{{ t('重試') }}</button></p><p v-if="!loading && !error && !notifications.length" class="subtle">{{ t('目前沒有通知') }}</p><div class="todo-notification-list"><button v-for="item in notifications" :key="item.id" :class="{ unread: !item.readAt }" @click="emit('open', item)"><span class="notification-state">{{ item.readAt ? t('已讀') : t('未讀') }}</span><strong>{{ item.actor }} {{ t(labels[item.event]) }}</strong><span>{{ item.title }}</span><time>{{ new Date(item.createdAt).toLocaleString(locale, { timeZone: displayTimeZone }) }}</time></button></div><div v-if="pageCount>1" class="pagination"><button class="text-button" :disabled="page<=1||loading" @click="emit('page',page-1)">{{ t('上一頁') }}</button><span>{{ page }} / {{ pageCount }}</span><button class="text-button" :disabled="page>=pageCount||loading" @click="emit('page',page+1)">{{ t('下一頁') }}</button></div></dialog>
</template>
<style scoped>
.todo-notifications { position: fixed; inset: 0 0 0 auto; margin: 0; width: min(480px,100vw); height: 100dvh; max-height: 100dvh; max-width: 100vw; border: 0; border-radius: 0; background: #fff; color: #242936; padding: 24px; overflow: auto; }.todo-notifications::backdrop { background: #171b2b66; }.todo-notifications header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 24px; }.mark-all-read { min-height: 44px; margin: -12px 0 12px; }.todo-notifications h2 { font-size: 20px; }.todo-notification-list button { display: block; width: 100%; text-align: left; padding: 16px 12px; border-bottom: 1px solid #daddE5; border-left: 3px solid transparent; }.todo-notification-list .unread { background: #f6f4ff; border-left-color: #6653bd; }.todo-notification-list strong { display: block; font-size: 14px; line-height: 1.8; margin-bottom: 6px; }.todo-notification-list span { display: block; font-size: 14px; overflow-wrap: anywhere; line-height: 1.8; }.todo-notification-list .notification-state { font-size: 12px; color: #5844a0; }.todo-notification-list time { display: block; font-size: 12px; color: #5f6673; margin-top: 10px; line-height: 1.8; }
</style>
